import type { Lesson, ModuleId } from '../lesson/types'
import { MODULES, moduleById } from './modules'
import manifest from './manifest.json'

/** Lightweight lesson metadata (generated by scripts/gen-manifest.mjs), enough for navigation and progress. */
export interface LessonMeta { slug: string; module: ModuleId; order: number; title: string; file: string }

export const LESSONS: LessonMeta[] = (manifest as LessonMeta[]).slice()
  .sort((a, b) => moduleById(a.module).n - moduleById(b.module).n || a.order - b.order)

// One lazily loaded chunk per lesson: its visualizer, data and text download only when the lesson is opened.
const loaders = import.meta.glob<{ lesson: Lesson }>('./*/[!_]*.tsx')
export const loadLesson = (m: LessonMeta) => loaders[m.file]().then((x) => x.lesson)

export const lessonsIn = (m: ModuleId) => LESSONS.filter((l) => l.module === m)
export const lessonBySlug = (slug: string) => LESSONS.find((l) => l.slug === slug)
export const lessonPath = (l: { module: ModuleId; slug: string }) => `/${l.module}/${l.slug}`

export function neighbours(slug: string) {
  const i = LESSONS.findIndex((l) => l.slug === slug)
  return { prev: LESSONS[i - 1], next: LESSONS[i + 1] }
}

export { MODULES }
export { TRACKS, modulesIn, moduleById } from './modules'
